-- (Specification rows the migration added to a product that had none are not in the backup; delete them
--  with: delete from product_specs where product_id = pid — only for a product that had no specs before.)

create table if not exists product_layout_backup_20261025 (
  id bigint generated always as identity primary key,
  product_id uuid not null,
  table_name text not null,
  row_data jsonb not null,
  deleted_at timestamptz not null default now()
);
create index if not exists product_layout_backup_20261025_product_idx on product_layout_backup_20261025 (product_id, table_name);
alter table product_layout_backup_20261025 enable row level security;
do $policy$
begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'product_layout_backup_20261025' and policyname = 'staff read product_layout_backup_20261025') then
    create policy "staff read product_layout_backup_20261025" on product_layout_backup_20261025 for select using (public.is_staff());
  end if;
end
$policy$;

