    (pid, 'image', 50, true, $json${"background":"cream","imageUrl":"https://static.wixstatic.com/media/1ac9e9_35620e980aaf4c0a8dfb59ba6b078407~mv2.png","alt":"Breaking the curve","decorative":false,"aspectRatio":"auto","alignment":"left","displayWidth":173,"spacingTop":"sm","spacingBottom":"sm"}$json$::jsonb),
